  // The gate comes into view; a guarded gate shows its rivals waiting in front of it.
  approach:(section,a)=>{if(section.run?.finale)return;if(a.guarded){runFlash('Rivals ahead! Get ready to cast','stumble');cue('select');}else runFlash('Gate ahead!','swamp');},
  skid:()=>{cue('slide');buzz(HAPTICS.hit);},
  // A free gate opens its task as soon as the creature has stopped; at a guarded gate the fight takes over.
  arrive:(section,a)=>{if(a.guarded){runFlash('Defeat the rivals to open the gate','stumble');gestureHint('fight','Tap anywhere to cast · tap a rival to aim · swipe up to jump');return;}const node=activeNode(state());if(node&&screen==='play'&&!task&&!modal&&!resultCard)interact(node.id);},
