function renderHome(){const scroll=$('.launch-body')?.scrollTop||0;homeFraming(onboarding?'onboard':'camp');document.body.classList.add('opening');document.body.classList.toggle('onboarding',onboarding);const c=setupContext();$('#ui').innerHTML=onboarding?onboardingMarkup(c):campMarkup(c);const body=$('.launch-body');if(body)body.scrollTop=scroll;}
function lessons(grade=unit().grade){if(![5,6,7,8].includes(grade))return;showModal('Choose your lesson',lessonMarkup({grade,units,journeys:save.journeys,selected:save.selected,teamName:partner().name,topics:LESSON_TOPICS}),{kind:'lesson-browser'});}
function graphicsMenu(){const rows=['explore','task','evolution'].map(phase=>{const m=world.frameMetrics?.snapshot(phase);return `<li>${phase}: ${m?.samples?`${Math.round(m.fps)} fps · p95 ${m.p95.toFixed(1)} ms · ${m.drawCalls} draws · ${Math.round(m.triangles/1000)}k triangles · ${Math.round(m.slow30*100)}% over 33 ms · session worst ${m.sessionWorst.toFixed(1)} ms (${m.samples} recent frames)`:'no play samples yet'}</li>`;}).join('');showModal('Graphics and performance',`<p>Target: 60 fps where practical; stable 30 fps on slower phones. Change settings, play a stretch, then return here to compare observations.</p><div class="graphics-grid">${Object.keys(QUALITY).map(p=>`<button data-do="graphics-preset" data-value="${p}" aria-pressed="${graphics.preset===p}">${p}</button>`).join('')}</div><h3>Resolution cap</h3><div class="graphics-grid">${[.75,1,1.5].map(v=>`<button data-do="graphics-resolution" data-value="${v}" aria-pressed="${graphics.resolution===v}">${v}×</button>`).join('')}</div><button class="secondary wide" data-do="graphics-shadows">Shadows: ${graphics.shadows?'on':'off'}</button><h3>Effects</h3><div class="graphics-grid">${['low','medium','full'].map(v=>`<button data-do="graphics-effects" data-value="${v}" aria-pressed="${graphics.effects===v}">${v}</button>`).join('')}</div><button class="secondary wide" data-do="graphics-adaptive">Adaptive resolution: ${graphics.adaptive?'on':'off'} · ${world.adaptiveResolution?.ratio?.toFixed(2)||graphics.resolution}×</button><h3>Loading and resources</h3>${(()=>{const p=performanceMonitor.startup(),m=world.renderer?.info?.memory||{},c=world.formAssets?.snapshot();return `<p>Opening requests: ${p.requestCount||0} · ${(p.transferBytes/1048576||0).toFixed(2)} MiB reported transferred. Cache and browser restrictions can make sizes unavailable.<br>Renderer: ${m.textures||0} textures · ${m.geometries||0} geometries. Creature cache: ${c?.templates||0}/2 forms.<br>Export the device report for the startup breakdown and resource samples.</p>`;})()}<h3>Recent play observations</h3><ul class="frame-observations">${rows}</ul><p>Frame intervals are observed on this browser, with separate exploration, task and evolution samples. These are not GPU timings or a device certification. Menus and hidden-tab gaps are excluded. Test touch, heat and sustained play on real phones.</p><button class="secondary" data-do="graphics-reset">Start a fresh measurement</button><p><a href="partner-preview.html?partner=${partner().id}&level=${journey().level}">Inspect creature animations →</a></p><h3>Device test checklist</h3><p>Play for 15 minutes, include tasks, combat and evolution, then record what you observed. Unchecked items remain untested.</p>${VISUAL_CHECKS.map(([id,label])=>`<label class="device-check">${label}<select data-device-check="${id}"><option value="not-tested">Not tested</option><option value="pass" ${deviceChecks[id]==='pass'?'selected':''}>Pass</option><option value="fail" ${deviceChecks[id]==='fail'?'selected':''}>Needs work</option></select></label>`).join('')}<button class="primary wide" data-do="device-export">Export device report</button>`);}
function saveGraphics(){applyGraphics(world,graphics,typeof devicePixelRatio==='number'?devicePixelRatio:1);world.frameMetrics?.reset();try{localStorage.setItem(GRAPHICS_KEY,JSON.stringify(graphics));}catch{toast('Graphics changed for this session. Device settings could not be saved.');}graphicsMenu();}
// Install / full-screen tips shown in How to play, matched to the device.
