function showUpdate(){if(document.getElementById('update-banner'))return;const b=document.createElement('button');b.id='update-banner';b.type='button';b.textContent='New version available · tap to update';b.addEventListener('click',()=>{try{persist();}catch{}location.reload();});document.body.append(b);}
function modeSwitch(){return RUNNER?'<p><strong>Classic paths:</strong> walk the shorter trail with the joystick instead of running. It keeps its own save.</p><button class="secondary wide" data-do="play-mode" data-value="classic">Play classic paths</button>':'<p><strong>Runner paths:</strong> run between gates in three lanes: jump, slide and dodge.</p><button class="secondary wide" data-do="play-mode" data-value="runner">Back to runner paths</button>';}
function appTips(){if(installed())return'';const tip=isAppleTouch()?'<p><strong>Play like an app:</strong> tap Share, then <em>Add to Home Screen</em>. Maxima then opens full screen and keeps lessons you have played for weak Wi-Fi.</p>':canInstall()?'<p><strong>Play like an app:</strong> use <em>Install</em> on the opening card. Maxima then opens full screen and keeps lessons you have played for weak Wi-Fi.</p>':'';return tip+(fullscreenAvailable()?`<button class="secondary wide" data-do="fullscreen">${inFullscreen()?'Leave full screen':'Play full screen'}</button>`:'');}
function help(){showModal('The Windward Trails',`<p>You are ${esc(save.nickname)}. Each <strong>run</strong> takes about five to eight minutes: four English tasks, one rival group, one trail trial and a reward chest at the end. Five runs make a week and cover all twenty activity types.</p><p><strong>Your teams:</strong> each team has its own levels, arena unlocks, Wordex and checkpoints for every lesson. Switch back to continue that team’s journey. Coins and purchased looks are shared.</p><p><strong>Growing:</strong> complete all 20 English checkpoints in each arena. In Whisperwood, checkpoints 5, 10 and 15 earn Forms 1, 2 and 3; its boss earns Form 4. Skyreach uses the same checkpoints for Forms 5, 6 and 7; its boss earns Form 8. Stormglass checkpoint 10 earns Form 9; its final boss earns Form 10. Both modes follow this journey. You can stop and resume from a saved checkpoint. Guardians at the end of each arena unlock the next arena. Wordex stars track recall across days separately; they never block evolution.</p><p><strong>Fresh practice:</strong> new expeditions shuffle their mechanisms and language. Unseen material comes first, with some familiar practice and delayed review of mistakes. Your current task stays exactly as you left it.</p><p><strong>Rush:</strong> Open coin trails accelerate to a run. Tap Boost while moving, or press Shift, for a short burst. Coins refill boost and build a chain. Hazards, rivals and gate approaches slow you down. English checkpoints pause the action.</p><p><strong>Moving:</strong> on phones use the left joystick, the Jump button and your elemental attack. On a keyboard use W / ↑ forward, S / ↓ back, A and D to turn, Space to jump and J or F to cast. Near a rival your creature faces it: A / D sidestep and W / S approach or retreat. Tap <strong>Follow</strong> to walk to the next discovery.</p><p><strong>Rivals:</strong> Rumblebud charges along an amber line: step aside or jump, then strike while it recovers. Brambleguard slams a marked sector: sidestep and strike its side or back. Mistcap sends purple rings: jump over them and strike while its cap is lowered.</p><p><strong>Trials:</strong> wait in alcoves for boulders, shelter from wind, ride turquoise platforms, follow green gaps between thorns, strike crystal cores when their shells open, and try gold ledges for bonus coins. Falling never costs English progress or coins.</p><p><strong>Every day:</strong> three daily quests pay coins. Rest days never break your trail streak. Coins buy wind trails, hats, coat colours and camp decorations in the Wardrobe.</p><p>Progress saves on this device. Export a backup from the journal to move devices.</p><button class="primary wide" data-do="close-modal">Follow the wind →</button>${modeSwitch()}${appTips()}`);}
function trailShopMarkup(){const w=save.wallet;return shopMarkup({tab:'trail',trails:TRAILS,owned:w.owned,equipped:w.equipped,hat:w.hat,coat:w.coat,camp:w.camp,balance:coinText(),nickname:save.nickname});}
function trailShop(){const w=save.wallet;showModal('Wardrobe',shopMarkup({tab:shopTab,trails:TRAILS,owned:w.owned,equipped:w.equipped,hat:w.hat,coat:w.coat,camp:w.camp,balance:coinText(),nickname:save.nickname}));}
function journal(){const j=journey(),e=state(),chapter=chestPending(e)?runChapter(e):Math.min(4,Math.floor(e.index/4));showModal('Journey journal',`${e.pacingVersion>=1?`<p><strong>${esc(sceneBeat(e,chapter).title)}</strong><br>${esc(sceneBeat(e,chapter).text)}${sceneBeat(e,chapter).discovered?' · Discovery found':''}</p>`:''}<p>${esc(partner().name)} · ${esc(unit().title)} · Grade ${unit().grade} · Form ${j.level}</p>${growthBar(growthState())}<p>${esc(AREAS[save.area].name)} · Run ${(j.runCount||0)+1} · ${esc(expeditionTitle(save.area,chapter,CHAPTERS[chapter][0]))}<br><strong>Next:</strong> ${esc(chestPending(e)?'Open the reward chest':activeNode(e)?.object||'Choose a path at the fork')}</p><div class="milestone-summary"><strong>${e.index} / 20 activities on this path</strong><small>Each run covers four formats; five runs complete the path and cover all twenty.${e.checkpoint?` Last saved: ${esc(activity(e.checkpoint.type).object)}.`:''}</small></div><div class="trail-checklist">${ACTIVITIES.map(a=>`<div><span>${a.symbol} ${esc(a.label)}</span><b>${e.completed.some(c=>c.type===a.id)?'✓ this path':'·'}</b></div>`).join('')}</div><p>${dueCount(j)} words are ready for review · ${masteredCount(j)} remembered across several days. Difficult language returns after other activities when a matching mechanism is available.</p><p>${j.stats.correct} accepted steps · ${j.stats.mistakes} corrections · ${j.stats.hints} hints</p><button class="secondary" data-do="wordex">Wordex →</button><button class="secondary" data-do="trails">Wardrobe · ${coinText()} coins →</button><button class="secondary wide" data-do="controls">Controls</button><button class="secondary wide" data-do="graphics">Graphics and performance</button><button class="secondary wide" data-do="music">Music: ${save.music===false?'off':'on'}</button>${typeof navigator!=='undefined'&&typeof navigator.vibrate==='function'?`<button class="secondary wide" data-do="haptics">Vibration: ${save.haptics===false?'off':'on'}</button>`:''}<div class="journal-actions"><button class="secondary" data-do="export">Export backup</button><button class="secondary" data-do="import">Import backup</button>${j.level?'<button class="secondary" data-do="evolution-replay-earned">Replay latest evolution</button>':''}<button class="secondary" data-do="restart">Restart this unit</button></div>`);}
async function enter({reuseForm=false}={}){document.body.classList.remove('opening','onboarding');locked=true;syncWorld();try{if(!reuseForm){loadingNotice('Loading your creature…');await world.loadForm(journey().level);}}finally{locked=false;clearLoading();}screen='play';locked=false;document.body.classList.add('playing');world.setView(false);world.paused=false;const day=markPlayed(save);persist();if(day.first&&save.tutorial)toast(welcomeLine(day,day.gap));voice.load().catch(()=>{});const pending=state().pendingEvolution;if(pending){await evolution(!!pending.boss&&journey().completed,{from:pending.from,to:pending.to,path:true});return;}if(state().battle){showBattle();return;}if(guardianReady(journey(),state())&&state().index===20&&!chestPending(state())){showBattle();return;}if(state().active){task=state().active;openTaskView();return;}renderPlay();warmNextForm();if(!save.tutorial){save.tutorial=true;persist();}if(!controlPrefs.tutorial)startTutorial();}
function renderPlay(){keepAwake(true);languageFeedback=null;const previewNode=activeNode(state());if(previewNode&&previewNode.type!=='exit'&&world.prepareMechanismPreview&&!world.hasMechanismPreview?.(previewNode.id)){const e=state(),j=journey(),practice=JSON.parse(JSON.stringify(j.practice||{})),preview=e.active||makeTask(unit(),previewNode.type,`${e.id}:${e.index}`,`${e.contentSeed||e.id}:${e.index}:${previewNode.type}`,taskPriority(),j.level,practice);world.prepareMechanismPreview(preview);}document.body.classList.remove('opening','onboarding');screen='play';task=null;resultCard=false;feedbackText='';correction=null;nearId='';document.body.classList.remove('guardian-choice');const e=state(),j=journey(),pending=chestPending(e),chapter=Math.min(4,Math.floor(e.index/4)),fork=!pending&&!e.choices[chapter]&&e.index<20,done=pending?4:e.index%4,g=growthState();$('#ui').innerHTML=`<button class="play-status" data-do="journal" aria-label="${esc(save.nickname)} Form ${j.level}, run ${(j.runCount||0)+1}, ${done} of 4 tasks. Open journey journal."><img src="${partnerPortrait(partner().id,j.level)}" alt=""><span class="status-text">Form ${j.level}<small id="goal-readout">${esc(goalText(g))}</small></span><span class="rush-chip" id="rush-readout" title="Coin chain and boost fuel" hidden></span><span class="status-growth" aria-hidden="true"><i style="width:${Math.round(g.progress*100)}%"></i></span><b>${icon('coin')} <span id="coin-count">${coinText()}</span></b></button><div class="play-dock"><div class="traversal-hint" id="traversal-hint">${fork?esc(forkHint(e,chapter)):pending?'Your reward chest waits just ahead!':''}</div><div class="joystick" id="joystick" aria-label="Move your creature"><div id="joystick-thumb"></div></div>${fork?`<div class="fork-actions"><button data-do="branch" data-side="left" aria-label="Left: ${esc(CHAPTERS[chapter][1])}. ${esc(firstOnBranch('left'))}">${icon('left')}<small>Left</small></button><button data-do="branch" data-side="right" aria-label="Right: ${esc(CHAPTERS[chapter][2])}. ${esc(firstOnBranch('right'))}">${icon('right')}<small>Right</small></button></div>`:`<button class="attack-button" id="attack-button" style="--cast-color:${elementalAttack(partner().id).color}" data-do="attack" aria-label="${elementalAttack(partner().id).name}: ranged elemental attack">${icon('attack')}<small>Cast</small></button><button class="jump-button" id="jump-button" data-do="jump" aria-label="Jump">${icon('jump')}<small>Jump</small></button><div class="context-action" id="context-action"><small id="context-name"></small><button id="context-button" data-do="follow" aria-label="Follow trail to the next discovery">${icon('follow')}<small>Follow</small></button></div>`}</div>`;$('#task-layer').innerHTML='';controls.update();joystick();}
function firstOnBranch(side){const e=state(),c=Math.floor(e.index/4),copy={...e,choices:e.choices.slice()};copy.choices[c]=side;return activity(currentType(copy)).object+' first'+(e.pacingVersion>=1?' · '+routePreview(e,c,side).text:'');}
let disposeStick=null;function joystick(){disposeStick?.();const handlers=[bindStick($('#joystick'),$('#joystick-thumb'),(x,z)=>world.setInput(x,z),()=>persist(),window,document),bindActionButton($('#jump-button'),()=>world.jump(),window,document),bindActionButton($('#attack-button'),()=>world.attack?.(),window,document)];disposeStick=()=>handlers.forEach(dispose=>dispose());}
