function frame(){if(!world||!nav)return;{const r=nav.runner,run=r?.running&&r.section?.run,live=run&&screen==='play';runProgress(live?Math.max(0,r.s)/run.length:null);powerChips(live?r.power:null);speedLines(live?Math.max(0,Math.min(1,(r.speed-run.start)/(run.top-run.start)))*.75+(r.burst>0||r.has('dash')?.5:0):0);}if(screen==='evolution'&&evoState?.returnAt&&!document.hidden&&Date.now()>=evoState.returnAt){evoState.returnAt=null;finishEvolution();return;}if(world.guardianStage?.active&&screen==='play'){guardianFrame();return;}world.measurementPhase=document.hidden?null:screen==='evolution'?(world.evolution&&!world.evolution.resolved?'evolution':null):screen==='play'&&!modal&&!resultCard&&!locked?(task?'task':'explore'):null;gameAudio.frame({footfallSerial:world.proceduralMotion?.footfallSerial??world.locomotion?.footfallSerial??null,partner:partner().id,position:nav.player,height:nav.height,moving:nav.moving,grounded:nav.grounded,stage:nav.jumpStage,area:save.area,active:!save.muted&&!document.hidden&&screen==='play'&&!task&&!modal&&!resultCard&&!locked,scene:document.hidden?null:screen==='evolution'?'evolution':screen==='home'?'camp':state().battle||guardianChase()?'guardian':(runnerMusic()?'run-':'')+(['whisperwood','skyreach','stormglass'][save.area]||'whisperwood'),intensity:screen==='play'&&(nav.combat?.blocking?.active||nav.trials?.focus||state().battle)?1:screen==='play'&&nav.section?.trial&&!travelState(state()).completed.includes(nav.section.index)?.45:0});const rushReadout=$('#rush-readout');if(rushReadout&&nav.rush){const chain=nav.rush.chain|0,text=chain>1?`×${chain}`:'';if(rushReadout.textContent!==text)rushReadout.textContent=text;rushReadout.hidden=!text;rushReadout.style?.setProperty?.('--fuel',Math.round(nav.rush.fuel*100)+'%');}if(pendingCompletion){const p=pendingCompletion;if(screen!=='play'||nav.state!==p.expedition){pendingCompletion=null;}else if(!modal&&!document.hidden&&Date.now()>=p.at){pendingCompletion=null;if(p.next==='guardian')showBattle();else if(p.next==='camp')home();else returnTrail();toast(p.notice);return;}}if(pendingSummary&&!modal&&!document.hidden&&Date.now()>=pendingSummary.at){const p=pendingSummary;pendingSummary=null;runSummary(p);return;}world.paused=screen!=='play'||!!task||modal||resultCard||locked||tutorialOpen;if(screen!=='play'||task||modal||resultCard)return;const e=state(),chapter=Math.min(4,Math.floor(e.index/4)),chest=chestPending(e)?world.chestPoint:null;if(chest&&!locked&&!nav.jumping&&Math.hypot(nav.player.x-chest.x,nav.player.z-chest.z)<1.6+nav.radius){openChest();return;}if(!chest&&e.index<20&&!e.choices[chapter]&&Math.abs(nav.player.x)>1.3&&Math.abs(nav.player.z-(-chapter*CHAPTER_LENGTH+2))<5){branch(nav.player.x<0?'left':'right');return;}const stretch=nav.section,travelHint=$('#traversal-hint');const keyboardHint=$('.desktop-controls');if(keyboardHint)keyboardHint.textContent=(nav.combat?.blocking?.active||nav.trials?.focus)?'W / S approach / retreat · A / D sidestep · Space jump · J / F strike':'W / ↑ forward · S / ↓ back · A / D turn · Space jump · J / F strike';if(travelHint){const done=stretch&&travelState(state()).completed.includes(stretch.index);const hintText=nav.runner?.running?runnerCoach(nav.runner):chestPending(e)?'Your reward chest waits at the clearing ahead!':!e.choices[chapter]?forkHint(e,chapter):(nav.combat?.lastFeedback?.until>nav.courseTime&&!nav.combat.group.some(r=>r.active&&['windup','charge','seedwindup','seedstrike','sporewindup','pulse'].includes(r.phase))?nav.combat.lastFeedback.text:'')||approachGuidance(nav)||(nav.combat?.blocking?enemyHint(nav.combat.blocking)+' · '+nav.combat.remaining+' remaining':stretch?.trial&&!done?trialHint(stretch):stretch&&!done?({coins:nav.rushEnabled?'Coin trail · jump for high coins · Boost / Shift':'Follow the coin trail',rocks:save.mode==='relaxed'?'Rock crossing · edge jumps assisted · cracked stones crumble':'Rock crossing · move + jump · cracked stones crumble',plants:'Purple spores hurt · amber means a burst is coming',steps:'Climb the old stone stairs'}[stretch.kind]):'');updateTrailHint(travelHint,hintText,{urgent:!!nav.combat?.blocking?.active||!!nav.trials?.blocking||!!(stretch&&!done&&['rocks','plants'].includes(stretch.kind))});}const nearest=nav.jumping||nav.recovery>0?null:nav.nearest(),context=$('#context-action');if(context){context.classList.toggle('hidden',!!nav.combat?.blocking||!!nav.trials?.blocking);const b=$('#context-button'),rushBoost=!nearest&&nav.rushEnabled&&nav.moving&&!nav.path.length;if(b&&rushBoost){b.dataset.do='boost';b.innerHTML=icon('follow')+'<small>Boost</small>';b.setAttribute('aria-label','Boost while moving through a coin section');}if(b&&!rushBoost&&(b.dataset.do!==(nearest?'interact':'follow')||nearest&&nearId!==nearest.id)){b.dataset.do=nearest?'interact':'follow';b.innerHTML=icon(nearest?'use':'follow')+(nearest?'<small>Use</small>':'<small>Follow</small>');b.setAttribute('aria-label',nearest?`${nearest.type==='exit'?'Finish expedition':'Interact with'} ${nearest.object}`:'Follow trail to the next discovery');}if(nearest)nearId=nearest.id;}const attack=$('#attack-button');if(attack){attack.disabled=!!nav.combat?.attack||nav.combat?.cooldown>0||nav.recovery>0;const rival=nav.combat?.blocking;attack.classList.toggle('opening',(nav.trials?.canStrike()||false)||!!rival&&nav.combat.canDamage(rival,{kind:nav.jumping?'jump':'strike'})&&Math.hypot(nav.player.x-rival.x,nav.player.z-rival.z)<=elementalAttack(partner().id).range);const small=attack.querySelector?.('small');if(small)small.textContent='Cast';}const jump=$('#jump-button');if(jump)jump.disabled=nav.recovery>0||nav.jumpStage==='anticipation'||nav.jumpStage==='air'&&nav.vy>0;if(nearest&&nearest.distance<4.05&&nav.moving&&Date.now()>autoOpenAfter&&!nav.jumping){interact(nearest.id);return;}if(Date.now()-lastSnapshot>1000){lastSnapshot=Date.now();persist();}}
function interact(id){if(screen!=='play'||modal||task||resultCard||locked||nav.jumping||nav.combat?.blocking||nav.trials?.blocking)return;const node=activeNode(state());if(!node||id!==node.id||Math.hypot(nav.player.x-node.x,nav.player.z-node.z)>5.3)return;persist();if(node.type==='exit'){endRoute();return;}const e=state();e.active??=makeTask(unit(),node.type,`${e.id}:${e.index}`,`${e.contentSeed||e.id}:${e.index}:${node.type}`,taskPriority(),journey().level,journey().practice);task=e.active;persist();openTaskView();}
function openTaskView(){languageFeedback=null;document.body.classList.remove('task-arriving','returning-to-play');document.body.classList.add('task-arriving');setTimeout(()=>document.body.classList.remove('task-arriving'),850);world.onMechanismSeat=()=>{if(task&&!document.hidden&&!modal)cue('seat');};if(task?.type?.startsWith('listen'))voice.load().then(()=>voice.prefetch((task?.pairs||task?.rounds||[]).map(x=>x.spoken).filter(Boolean))).catch(()=>{});document.body.classList.remove('guardian-choice');document.body.classList.add('in-task');world.setView(false,activeNode(state())?.id||null,!!state().battle);world.taskStyle=['sentence','halves'].includes(task.type)?'side':'front';world.paused=true;$('#ui').innerHTML='';feedbackText=task.kind==='pairs'?'Tap one piece, then its matching partner. Completed connections stay in place.':task.rounds[task.round]?.kind==='blocks'?'Tap the next sentence block. Correct pieces stay fitted.':'Read the mechanism, then tap a piece to use it.';renderTask();}
function renderTask(){if(!task)return;const t=task,a=activity(t.type),plan=guidancePlan(world.showMechanism(t),t,languageFeedback),round=t.kind==='pairs'?`${t.matched.length} / 3 connected`:`${Math.min(3,t.round+1)} / 3`;$('#task-layer').innerHTML=`<div class="mechanism-hud"><div><span>${esc(a.object)} · ${round}</span><strong>${esc(t.type==='correct'?'Complete the inscription':t.type==='qa-pairs'?'Questions above · answers below':a.label)}</strong></div><button data-do="close-task" aria-label="Save and step away">${icon('close')}</button></div>${mechanismMarkup(plan)}<div class="mechanism-tools">${languageFeedback?languageFeedbackMarkup(languageFeedback):`<p role="status">${esc(feedbackText||'Touch the pieces on the mechanism.')}</p>`}<div>${t.kind==='pairs'?`<button data-do="inspect-task" aria-pressed="${!!world.mechanism?.inspect}">${world.mechanism?.inspect?'All pairs':'Read closely'}</button>`:''}<button data-do="hint">${icon('help')}${esc(languageCoach.hintLabel(t))}</button>${t.type.startsWith('listen')?'<button data-do="speech-text">Reading support</button>':''}<button data-do="task-tools">${icon('more')}More</button></div></div>`;}
function speak(text){text=spokenRequest(text);gameAudio.reading=true;gameAudio.silence();voice.say(text,{rate:save.mode==='relaxed'?.94:1,onend:()=>{gameAudio.reading=false;}}).then(ok=>{if(!ok)browserSpeak(text);}).catch(()=>browserSpeak(text));}
// Browser voice fallback, used only when a recorded clip is missing or audio cannot start.
function browserSpeak(text){if(!speechSupported){showSpeech();toast('Speech is unavailable here. Reading support is enabled.');return;}try{gameAudio.reading=true;gameAudio.silence();speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=save.mode==='relaxed'?.85:1;const voices=speechSynthesis.getVoices();u.voice=femaleEnglishVoice(voices);if(!u.voice){gameAudio.reading=false;showSpeech();toast('A clear English voice is unavailable. Reading support is enabled.');return;}u.lang=u.voice.lang;u.onend=()=>{gameAudio.reading=false;};u.onerror=()=>{gameAudio.reading=false;if(task){showSpeech();toast('Audio could not play. Reading support is enabled.');}};speechSynthesis.speak(u);}catch{showSpeech();}}
